import{_ as t,H as i,f as n,i as a}from"./chunks/framework.BH2BK_3i.js";const D=JSON.parse('{"title":"19 | 值对象（中）：值对象有什么好处？","description":"","frontmatter":{},"headers":[{"level":2,"title":"对象的内存布局","slug":"对象的内存布局","link":"#对象的内存布局","children":[]},{"level":2,"title":"实体的内存布局","slug":"实体的内存布局","link":"#实体的内存布局","children":[]},{"level":2,"title":"值对象的内存布局","slug":"值对象的内存布局","link":"#值对象的内存布局","children":[]},{"level":2,"title":"实体的数据库布局","slug":"实体的数据库布局","link":"#实体的数据库布局","children":[]},{"level":2,"title":"值对象的数据库布局","slug":"值对象的数据库布局","link":"#值对象的数据库布局","children":[]},{"level":2,"title":"值对象的其他优点","slug":"值对象的其他优点","link":"#值对象的其他优点","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"手把手教你落地DDD/19｜值对象（中）：值对象有什么好处？.md","filePath":"手把手教你落地DDD/19｜值对象（中）：值对象有什么好处？.md","lastUpdated":1795557830000}'),s={name:"手把手教你落地DDD/19｜值对象（中）：值对象有什么好处？.md"};function p(E,e,r,o,g,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_19-值对象-中-值对象有什么好处" tabindex="-1">19 | 值对象（中）：值对象有什么好处？ <a class="header-anchor" href="#_19-值对象-中-值对象有什么好处" aria-label="Permalink to &quot;19 | 值对象（中）：值对象有什么好处？&quot;">​</a></h1><p>你好，我是钟敬。</p><p>上节课我们讲了值对象的基本概念和编程方法。实体和值对象的差别大体可以总结成这句话：实体是一个“东西”，而值对象是一个“值”，往往用来描述一个实体的属性。</p><p>学完前面的内容，不知道你会不会有这样的疑问：我们花了这么大的功夫来区分实体和值对象，那么识别值对象有什么好处呢？今天我们就来聊这个问题。</p><p>值对象的优点，主要体现在内存和数据库布局的灵活性上。有了这种灵活性，就可以根据性能、编程方便性等因素，决定值对象的不同实现方式。其次，值对象的不变性也会带来更高的程序质量。这些优点，都是实体所不具备的。</p><p>那么，这里说的“布局”指什么呢？我们慢慢讲。先提示一下，后面有不少图片和代码，你可以边看文稿，边听我说。</p><h2 id="对象的内存布局" tabindex="-1">对象的内存布局 <a class="header-anchor" href="#对象的内存布局" aria-label="Permalink to &quot;对象的内存布局&quot;">​</a></h2><p>先说内存里的布局，也就是程序运行的时候，对象在内存里是怎么存储的。为了说明这个问题，我们可以利用 UML 的对象图（Object Diagram）来分析。</p><p>假如有一个员工，名字叫“张三”，出生日期是“1990 年 1 月 1 日”，员工号是“1001”。他有两个技能：一个是 Go 语言，做过 3 年，达到中等水平；另一个是 Java 语言，做过 10 年，达到高级水平。他还有两段工作经历：从“2017 年 1 月 1 日”到“2022 年 1 月 1 日”在“ABC Inc”公司工作；从“2014 年 1 月 1 日”到“2016 年 12 月 31 日”在“123 Inc”工作。</p><p>那么，表示这个员工的对象图，可以画成下面这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/1.png" alt=""></a></p><p>这个图看起来有点像领域模型图，但其实不是。领域模型的图是“类图”，每个方框代表一个类。但是对象图的每个方框代表一个对象。每个框的名字都有一个下划线，例如 张三 : Emp。在 UML 里，这种名字有下划线的框就表示一个对象，也就是一个类的实例。</p><p>对象名里有一个冒号，冒号前面是对象的名字，以便于描述；冒号后面是这个对象的类型。例如 张三 : Emp 这个对象，对象名是“张三”，对象的类型是 Emp 型。不过，对象的名字常常被省略掉。</p><p>箭头表示对象之间的引用，从技术的角度来说，代表了被引用对象的地址。</p><p>一个对象有很多属性，在对象图里可以用等号写出属性值。对象图和类图的一个区别就是对象图的属性有值，而类图没有。这是因为，只有具体到一个对象的时候，我们才会知道对象的属性值；而类只是对象的模版，所以只知道属性的类型，不知道值。</p><p>有了对象图，就可以表示对象在内存里的布局了。每个对象都占有一片内存空间，通过引用来互相关联。</p><p>你可能会发现，有些属性自身也是对象，例如 : Emp 对象的 num（员工号）属性是字符串（String）型，它本身也是个对象。如果我们把所有对象都展开的话，对象图就成了下面的样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/2.png" alt=""></a></p><p>这个图更接近内存里真实的情况。像类图一样，对象图里也可以用“角色”表示属性名。另外，再看一看 Golang : Skill 对象，里面的 duration 属性是整型（int），是一种基本数据类型，所以写在对象框的内部，说明 duration 所占的内存包含在 :Skill 对象内部。而其他几个属性本身是对象，自己占有一块专门的内存，不过， :Skill 保存它们的引用也是要花费内存的。</p><p>上面两个图要表达的含义基本是等价的。前一种比较简洁，也比较常用。后一种是为了更细致地理解原理。到底采用哪种形式，取决于我们想强调什么。</p><p>现在我们头脑中是不是已经可以想象出来，一个对象和它关联的对象一起，在内存中组成了一个“图”（graph）。有了这个工具，我们就可以比较实体和值对象在内存布局上的不同了。</p><h2 id="实体的内存布局" tabindex="-1">实体的内存布局 <a class="header-anchor" href="#实体的内存布局" aria-label="Permalink to &quot;实体的内存布局&quot;">​</a></h2><p>对于实体而言，关键是把握一个原则：在同一个线程里，一个实体对象在内存空间里只能出现一次。也就是说，如果同一个实体在内存里被多个对象引用，那么这个实体必须被多个对象共享。</p><p>为了说明这个问题，咱们考虑一下员工和组织的关系。我们假设员工用对象导航的方式指向组织。张三和李四都是 IT 部的员工，那么对象图就是下面这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/3.png" alt=""></a></p><p>简单起见，我们忽略了这几个对象的其他属性。</p><p>目前这种内存布局是正确的。但是，有时候编程不小心，可能会导致下面这样的布局。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/4.png" alt=""></a></p><p>也就是说，同一时刻，在内存里有两个对象，表示同一个“IT 部”，这就违反了我们前面说的原则。</p><p>这样会有什么害处呢？假如我们改了其中一个组织对象的某个属性值，而另一个没有改，那么，在同一时刻，表示同一个部门的对象，就会存在不同的属性值，这在概念上是矛盾的，很可能会导致隐含的逻辑错误。</p><h2 id="值对象的内存布局" tabindex="-1">值对象的内存布局 <a class="header-anchor" href="#值对象的内存布局" aria-label="Permalink to &quot;值对象的内存布局&quot;">​</a></h2><p>说完了实体的内存布局，我们看看值对象有什么不同。</p><p>假设员工张三只有一段工作经验，是在 2014 年 1 月 1 日到 2016 年 12 月 31 日，在“123Inc”公司工作。我同样画了图，来表示内存布局。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/5.png" alt=""></a></p><p>为了简化一点，我们省略了员工的其他属性，时间段里的日期也没有进一步展开。在上面的图里，String（字符串）和 Period（时间段）都是值对象，各自占有一片内存空间。现在还没什么问题。</p><p>但假如还有另一个员工李四，他也在 2014 年 1 月 1 日到 2016 年 12 月 31 日，在“123 Inc”公司工作。那么，当张三和李四同时装入内存的时候，内存布局可以有两种：一种是共享值对象，另一种不共享。共享的情况可以看看下面这张图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/6.png" alt=""></a></p><p>我们看到，字符串和时间段都在两个工作经验之间共享。</p><p>不共享的情况，则是下面这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/7.png" alt=""></a></p><p>哪怕两个字符串的值是相同的，在内存里，也是重复出现的，内存空间多占了一倍。</p><p>那么，哪种是对的呢？答案是：两个都对！</p><p>这就奇怪了。对于实体来说，共享是对的，不共享就不对了；而对于值对象来说，共享和不共享，都对。这是为什么呢？</p><p>这是因为，值对象是不可修改的。所以，即使在内存里重复出现了，也不会像实体那样，由于修改而导致错误。</p><p>那么既然两者都可以，我们应该怎么选择呢？</p><p>要实现对象的共享，其实需要更复杂的编程，所以，值对象在内存里多数是不共享的。比如Java 语言里，默认情况下，字符串（String）、整数（Integer）等等都是不共享的。但有时候，JVM 会“偷偷地”把相同的字符串共享，以便节省内存空间。不过，这对程序员是不可见的，我们总是应该假定字符串没有共享。</p><p>那么，什么时候应该共享值对象呢？当值对象的体积比较大，数量比较多，共享值对象可以节省大量内存的时候，就可以采用共享的方式。这种用法实际上是一种设计模式，叫做“享元”，也就是共享的单元，英文是 Flytweight。有兴趣的话，你可以看看设计模式方面的书来进一步了解。</p><p>要注意一点：不论共享还是不共享，都只是一种实现上的选择，在概念层面，一个值对象总是唯一的。</p><p>现在可以看到，在内存里，我们既可以为了编程的方便，不共享值对象，也可以为了节省内存而共享，这种灵活性是实体所不具备的。这正是值对象的主要优点之一。</p><h2 id="实体的数据库布局" tabindex="-1">实体的数据库布局 <a class="header-anchor" href="#实体的数据库布局" aria-label="Permalink to &quot;实体的数据库布局&quot;">​</a></h2><p>说完了内存布局，我们再看看数据库布局。值对象在数据库的存储方式上也有更多的灵活性。</p><p>还是先考虑实体。我们继续用“张三和李四都在 IT 部”这个例子。和内存布局类似，在数据库表里，一个实体也只能有一条记录，不应该重复。例如，下面的存储方式是正确的。</p><p>员工（emp）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/8.png" alt=""></a></p><p>组织（org）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/9.png" alt=""></a></p><p>为了突出重点，我们省略了一些字段。在上面的员工表里面，张三和李四都通过 org_id 指向组织表里的同一条表示 IT 部的记录。</p><p>如果不小心弄成了下面这样，就错了。你可以把后面的数据和前面正确的做个对比。</p><p>员工（emp）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/10.png" alt=""></a></p><p>组织（org）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/11.png" alt=""></a></p><p>在组织表里，表示 IT 部的记录存了两次。这样，如果改了其中一条，另一条没有改，就会造成数据不一致，成了脏数据。</p><h2 id="值对象的数据库布局" tabindex="-1">值对象的数据库布局 <a class="header-anchor" href="#值对象的数据库布局" aria-label="Permalink to &quot;值对象的数据库布局&quot;">​</a></h2><p>现在再来看看值对象。我们继续用“张三和李四都有相同工作经验”的例子。员工表和工作经验表的内容是下面的样子，重点看工作经验表。</p><p>员工（emp）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/12.png" alt=""></a></p><p>工作经验（work_experience）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/13.png" alt=""></a></p><p>首先要说一下，在内存布局里面，时间段对象占有自己的内存空间，但在数据库里，并没有单独的“时间段表”。</p><p>相反，时间段的属性，也就是开始日期和结束日期，成了工作经验表里的两个字段。也就是说，时间段这个值对象被“嵌入”到工作经验表里了。这种“嵌入”到所属实体表的方式，正是值对象最常见的存储方式。</p><p>在数据库里是同一个表，在内存里却是不同的对象，这种数据库和内存的差异，称为阻抗不匹配。阻抗不匹配有多种形式，对象的嵌入式存储只是其中一种。在程序里进行数据存取的时候，就要进行转换，来消除这种不匹配。这种转换工作，是在仓库，也就是 Repository 中完成的。其实，消除这种阻抗不匹配，正是像 Hibernate 这样的 ORM 框架的主要目的之一。</p><p>像时间段这种比较小的值对象，一般都是嵌入式存储的。下面咱们再看一个不嵌入的例子。假设我们还要在系统里维护员工的地址。我们上节课说过，地址一般也是值对象。地址占的空间比较大，可以不用嵌入的方式，而是单独建立一个地址表。下面是张三在数据库里的数据。</p><p>员工（emp）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/14.png" alt=""></a></p><p>地址（addr）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/15.png" alt=""></a></p><p>现在假设，李四和张三是合租的房子，两个人的地址一样。换句话说，在概念上，两个人共享同一个地址。那么数据库里可以是下面的样子。</p><p>员工 (emp) 表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/16.png" alt=""></a></p><p>地址 (addr) 表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/17.png" alt=""></a></p><p>这时候，同一个地址信息存了两遍。这种情况对于实体是不对的，但对于值对象就没有问题，这同样是因为值对象的不变性。这种不变性在数据库操作的体现是：假如李四搬走了，换了地址，那么应该把和他相关的地址记录删除，再插入一条新地址，而不是改变地址表里原来的记录。</p><p>那么地址是否也可以按照共享的方式存储呢？也是可以的。就是下面这样。</p><p>员工（emp）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/18.png" alt=""></a></p><p>地址（addr）表的数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/19/19.png" alt=""></a></p><p>注意，现在两个表的依赖关系反过来了。地址表里不再有员工的 ID（emp_id），反之，员工表里有一个地址 ID（add_id），指向地址表。这样，就实现了地址的共享。这也是一种可行的做法。</p><p>让我们比较一下这两种做法。共享值对象的第一个好处，是节省存储空间。第二个好处，是很容易通过数据库查询找到住在同一个地址的人。</p><p>代价是，删除员工的时候不能随便删他的地址，因为可能别人还在用。而如果不删的话，如果所有使用这个地址的人都被删除了，就会留下垃圾数据。所以需要有清理垃圾数据的机制。由于现在硬盘都比较便宜了，所以，不共享的方式反而比较常用。</p><p>现在我们看到，和内存布局类似，值对象在数据库里也是既可以共享，也可以不共享，比实体更灵活。</p><h2 id="值对象的其他优点" tabindex="-1">值对象的其他优点 <a class="header-anchor" href="#值对象的其他优点" aria-label="Permalink to &quot;值对象的其他优点&quot;">​</a></h2><p>除了前面所说的灵活性以外，值对象还有一些其他的优点。这几点比较容易理解，我们简单说一下。</p><p>首先，很多程序的错误，是由于修改对象时不小心引起的。由于值对象是不可变的，所以采用值对象就可以减少出错的几率。</p><p>其次，在并发编程里，主要的错误来源也是可变性，使用值对象，也可以减少并发错误。</p><p>最后，函数式编程总是假定被操作的对象是不变的，因此，使用值对象也更容易进行函数式编程。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>好，今天就讲到这儿，下面来总结一下。</p><p>为了说明值对象的优点，这节课，我们首先介绍了“对象图”这个工具。其实对象图不仅能表达内存布局，也能在概念层面说明对象的关系，可以在领域建模的时候，作为类图的补充。</p><p>值对象的主要优点是，不论在内存还是数据库里，都可以选择共享和不共享的方式。这种灵活性，可以使我们在实现的时候，基于性能等原因进行优化。而这些优点，都是值对象的不变性带来的。</p><p>而实体不具备这样的优点，它们一般应该是共享的，所以需要更复杂的程序逻辑来保证。在特殊情况下，如果选择不共享，就要特别小心，避免错误。</p><p>此外，值对象还具有减少编程错误、利于并发以及利于函数式编程等好处。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>我们说，值对象在数据库里常常用“内嵌”的方式存储在实体表里。那么，实体是否也可以采用内嵌的方式呢？如果可以，什么情况下可以内嵌呢？</p></li><li><p>我们说，维护值对象的共享需要更复杂的编程。你可以尝试一下，用共享和不共享两种方式实现员工和地址，看看复杂在哪里。</p></li></ol><p>好，今天的课程结束了，有什么问题欢迎在评论区留言，下节课，我们继续讨论值对象在领域模型里的表达方式，以及值对象的本质。</p>',106)])])}const B=t(s,[["render",p]]);export{D as __pageData,B as default};
